class FileSystem:
    def __init__(self):
        # Store paths and values in a hash map
        self.paths = {}

    def createPath(self, path: str, value: int) -> bool:
        # Cannot create root or empty path
        if not path or path == "/" or path in self.paths:
            return False

        # Find parent by removing the last component
        parent = path[:path.rfind('/')]
        # Parent "" means the root, which always exists; otherwise it must already be created
        if parent and parent not in self.paths:
            return False

        self.paths[path] = value
        return True

    def get(self, path: str) -> int:
        return self.paths.get(path, -1)
